def maxGapPairs(nums, d):
    a = sorted(nums)
    n = len(a)

    def ok(k):
        for i in range(k):
            if a[n - k + i] - a[i] < d:
                return False
        return True

    lo, hi = 0, n // 2
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
